mapper.select:
SELECT a.* FROM ( select c.id,c.company from survey_consignor c left join survey_user_consignor uc on c.id = uc.consignor_id where c.delete_flag =0 and uc.delete_flag =0 and c.org_state=0
and uc.user_id = #{userId,jdbcType=BIGINT}
and c.org_attr != 2
and c.org_attr != 1
)a

select * from  survey_consignor

    delete_flag = 0 and org_state = 0

        and org_attr=#{orgAttr}
